reference_solution:
def maximum_keyboard_as(n):
    best = list(range(n + 1))
    for presses in range(1, n + 1):
        for breakpoint in range(1, presses - 2):
            best[presses] = max(best[presses], best[breakpoint] * (presses - breakpoint - 1))
    return best[n]

